def film_to_slide(apps, schema_editor):
    """An uploaded hero film (from before slides existed) becomes the first slide."""
    StoreInfo = apps.get_model("shop", "StoreInfo")
    HeroSlide = apps.get_model("shop", "HeroSlide")
    info = StoreInfo.objects.first()
    if info and info.hero_video and not HeroSlide.objects.exists():
        HeroSlide.objects.create(
            name="Hero film", kind="video", video=info.hero_video, video_mobile=info.hero_video_mobile,
            poster=info.hero_poster, image_mobile=info.hero_poster_mobile, show_text=True,
        )


